static uint32_t prepare_tlm_frame(const uint16_t data_id, uint8_t *const p_data_buf, const uint32_t data_buf_size);

/** @brief Try to push the provided telemetry preset entry to the queue for dispatch
 *
 *  The function reads the corresponding entry data from DataCache, COBS-encodes it and finally tries to
 *  push it to the telemetry queue for dispatch to storage. If something fails, it just traces a warning and exits.
 *
 *  @param[in/out] p_tlm_rt_ctx pointer to the currently active telemetry context
 *  @param[in] p_tlm_entry pointer to the preset telemetry entry read from NVM
 *
 *  @retval true: the entry was pushed to the dispatch queue successfully
 *  @retval false: the entry was not pushed to the dispatch queue
 */
static bool try_push_tlm_entry_to_queue(tlm_runtime_context_t *const p_tlm_rt_ctx, const TELEMETRY_tlm_preset_cfg_t *const p_tlm_entry);

/** @brief The operation prepares the hold timer to wait for the specified user time. The timer interval is part of
 *  the p_tlm_rt_ctx structure.
 *
 *  @param[in/out] p_tlm_rt_ctx pointer to the currently active telemetry context
 */
static void arm_hold_timer(tlm_runtime_context_t *const p_tlm_rt_ctx);

static uint32_t prepare_tlm_frame(const uint16_t data_id, uint8_t *const p_data_buf, const uint32_t data_buf_size)
{
    uint32_t frame_len = 0U;

    CRIT_ASSERT(NULL != p_data_buf);
    CRIT_ASSERT(data_buf_size > 0U);

    if (INVALID_TLM_SLOT_ASSIGNMENT != data_id)
    {
        dc_did_id dc_item_idx = dc_get_index_by_data_id(data_id);

        if (DC_DID_MAX != dc_item_idx)
        {
            uint32_t dc_data_size    = dc_get_data_size(dc_item_idx);
            uint32_t tlm_msg_buff_sz = sizeof(((tlm_runtime_context_t *)NULL)->tlm_msg_buffer);

            CRIT_ASSERT(dc_data_size <= TLM_BUF_SIZE);

            if (dc_data_size <= TLM_BUF_SIZE)
            {
                tlm_frame_hdr_t *p_frame_hdr  = (tlm_frame_hdr_t *)p_data_buf;
                uint8_t         *p_frame_data = &p_data_buf[sizeof(tlm_frame_hdr_t)];

                frame_len = sizeof(tlm_frame_hdr_t) + dc_data_size + sizeof(tlm_msg_footer_t);

                CRIT_ASSERT(tlm_msg_buff_sz >= frame_len);

                unix_time_precise_t data_ts = datetime_to_unix_precise_now();

                p_frame_hdr->timestamp    = data_ts.unix_ts;
                // set the timestamp in units of 0.1 ms
                p_frame_hdr->timestamp_precise = (uint16_t) ((((uint32_t) data_ts.ms * 1000) + data_ts.us) / 100);
                p_frame_hdr->rolling_cntr++;
                conops_get_hsm_active_state(&p_frame_hdr->obc_opmode);

                dc_data_status_t dc_status =
                    dc_get_raw_data(dc_item_idx,
                                    p_frame_data,
                                    tlm_msg_buff_sz,
                                    0U,
                                    dc_data_size);

                p_frame_hdr->msg_hdr.msg_type        = data_id;
                p_frame_hdr->msg_hdr.tlm_data_status = (uint8_t)dc_status;
                CRIT_ASSERT(dc_data_size <= UINT_MAX);
                p_frame_hdr->msg_hdr.data_len = (uint16_t)dc_data_size;

                p_frame_data += dc_data_size;

                ((tlm_msg_footer_t *)p_frame_data)->crc =
                    crc16_ccitt_table((const uint8_t *)p_frame_hdr, frame_len - sizeof(tlm_msg_footer_t));
            }
        }
    }

    return frame_len;
}

static bool try_push_tlm_entry_to_queue(tlm_runtime_context_t *const p_tlm_rt_ctx, const TELEMETRY_tlm_preset_cfg_t *const p_tlm_entry)
{
    CRIT_ASSERT(NULL != p_tlm_rt_ctx);
    CRIT_ASSERT(NULL != p_tlm_entry);

    bool     is_pushed_to_queue = false;
    uint32_t frame_len          = prepare_tlm_frame(p_tlm_entry->u16Data_id, p_tlm_rt_ctx->tlm_msg_buffer, sizeof(p_tlm_rt_ctx->tlm_msg_buffer));

    if (frame_len > 0U)
    {
        uint32_t cobs_frame_len = cobs_encode(p_tlm_rt_ctx->tlm_msg_buffer,
                                              frame_len,
                                              p_tlm_rt_ctx->tlm_msg_encode_buffer);

        // the following check ensures there is room for the frame delimiter byte
        BREAK_ASSERT((cobs_frame_len + 1U) <= sizeof(p_tlm_rt_ctx->tlm_msg_encode_buffer));

        if ((cobs_frame_len + 1U) <= sizeof(p_tlm_rt_ctx->tlm_msg_encode_buffer))
        {
            p_tlm_rt_ctx->tlm_msg_encode_buffer[cobs_frame_len++] = TLM_FRM_DELIMITER;

            is_pushed_to_queue = telemetry_queue_push(&p_tlm_rt_ctx->tlm_queue, p_tlm_rt_ctx->tlm_msg_encode_buffer, (uint16_t)cobs_frame_len);

            if (false == is_pushed_to_queue)
            {
                // Note: Even if res is false, which means there was no space in the queue, we will
                //       still continue with other slots because there may be enough space in the queue for them.
                ES_TRACE_WARN("[%u] skipping DC frame '%u' due to lack of space in queue", (uint8_t)p_tlm_rt_ctx->sm_instance_id, p_tlm_entry->u16Data_id);
            }
        }
        else
        {
            ES_TRACE_WARN("[%u] skipping DC frame '%u' because it is larger than the configured queue size of %lu byte(s)", (uint8_t)p_tlm_rt_ctx->sm_instance_id, p_tlm_entry->u16Data_id, (uint32_t)sizeof(p_tlm_rt_ctx->tlm_msg_encode_buffer));
        }
    }

    return is_pushed_to_queue;
}

static void arm_hold_timer(tlm_runtime_context_t *const p_tlm_rt_ctx)
{
    CRIT_ASSERT(NULL != p_tlm_rt_ctx);

    if (0 != p_tlm_rt_ctx->hold_period_s)
    {
        timer_start(&p_tlm_rt_ctx->hold_timer);
    }
    else
    {
        timer_stop(&p_tlm_rt_ctx->hold_timer);
    }
}
