{
    (void) instance_id;
    (void) pSMRoot;
    (void) pEvent;

    // USER_CODE_START::guard_is_hold_time_elapsed
    tlm_runtime_context_t *p_tlm_rt_ctx          = telemetry_cfg_get_ctx_u16(instance_id);
    bool                   is_hold_timer_elapsed = ((IS_TRUE(p_tlm_rt_ctx->hold_timer.is_running)) &&
                                  (true == timer_is_elapsed(&p_tlm_rt_ctx->hold_timer, p_tlm_rt_ctx->hold_period_s * 1000U)));

    if (true == is_hold_timer_elapsed)
    {
        timer_stop(&p_tlm_rt_ctx->hold_timer);
        p_tlm_rt_ctx->hold_period_s = 0U;
    }

    return is_hold_timer_elapsed;
    // USER_CODE_END::guard_is_hold_time_elapsed
}
