// GEN_OBJ_START::telemetry_sm_action_collect_telemetry
void telemetry_sm_action_collect_telemetry(const uint16_t instance_id, const sState_t * const pSMRoot, const sHSM_EventType_t * const pEvent)
{
    (void) instance_id;
    (void) pSMRoot;
    (void) pEvent;

    // USER_CODE_START::action_collect_telemetry
    tlm_runtime_context_t *p_tlm_rt_ctx = telemetry_cfg_get_ctx_u16(instance_id);

    uint16_t current_slot_idx = (p_tlm_rt_ctx->next_start_slot_idx < TELEMETRY_MAX_CONFIGURABLE_ENTRIES) ? p_tlm_rt_ctx->next_start_slot_idx : 0;
    uint16_t end_slot_idx     = (current_slot_idx + TELEMETRY_MAX_CONFIGURABLE_ENTRIES) % TELEMETRY_MAX_CONFIGURABLE_ENTRIES;
    bool     is_pushed_ok     = false;

    ES_TRACE_DEBUG("[%u] scan range is ['%u'..'%u']", (uint8_t)p_tlm_rt_ctx->sm_instance_id, current_slot_idx, end_slot_idx);

    telemetry_load_config(p_tlm_rt_ctx);

    // invalidate last skipped slot before next use
    p_tlm_rt_ctx->next_start_slot_idx = TELEMETRY_MAX_CONFIGURABLE_ENTRIES;

    do
    {
        TELEMETRY_tlm_preset_cfg_t tlm_entry = p_tlm_rt_ctx->preset_cfg.tlm_slots_setting[p_tlm_rt_ctx->active_preset_id][current_slot_idx];

        // has acquisition period elapsed?
        if ((true == tlm_entry.bActive) &&
            (tlm_entry.u16Acq_period_ms > 0U) &&
            (true == timer_is_elapsed(&p_tlm_rt_ctx->tlm_entry_timer[current_slot_idx], tlm_entry.u16Acq_period_ms)))
        {
            is_pushed_ok = try_push_tlm_entry_to_queue(p_tlm_rt_ctx, &tlm_entry);

            if ((TELEMETRY_MAX_CONFIGURABLE_ENTRIES == p_tlm_rt_ctx->next_start_slot_idx) &&
                (false == is_pushed_ok))
            {
                // preserve the first slot which was not successfully pushed to the dispatch queue as the starting slot for
                // the next collection round
                p_tlm_rt_ctx->next_start_slot_idx = current_slot_idx;

                ES_TRACE_DEBUG("[%u] will start from slot '%u' next round", (uint8_t)p_tlm_rt_ctx->sm_instance_id, p_tlm_rt_ctx->next_start_slot_idx);

                // there may be other failures during the preset scan because the loop will continue in a cyclic fashion
                // but next time we start from the slot which failed first
            }

            // reset acquisition time
            timer_start(&p_tlm_rt_ctx->tlm_entry_timer[current_slot_idx]);
        }

        current_slot_idx = (current_slot_idx + 1) % TELEMETRY_MAX_CONFIGURABLE_ENTRIES;
    } while (current_slot_idx != end_slot_idx);
    // USER_CODE_END::action_collect_telemetry
}
// GEN_OBJ_END::telemetry_sm_action_collect_telemetry

